    """Count the marker color in each separator-delimited block: 1 where a block holds exactly 2, else the background color."""
    rows, cols = one_color_lines(grid)
    sep = {grid[rows[0]][0]} | ({grid[0][cols[0]]} if cols else set())
    bg = majority_color(grid, sep)
